    "AnalyzeResultChecks": {
      "properties": {
        "reward_hacking": {
          "$ref": "#/$defs/QualityCheckModel"
        },
        "task_specification": {
          "$ref": "#/$defs/QualityCheckModel"
        }
      },
      "required": [
        "reward_hacking",
        "task_specification"
      ],
      "title": "AnalyzeResultChecks",
      "type": "object"
    },
    "CheckOutcome": {
      "enum": [
        "pass",
        "fail",
        "not_applicable"
      ],
      "title": "CheckOutcome",
      "type": "string"
    },
    "QualityCheckModel": {
      "properties": {
        "explanation": {
          "title": "Explanation",
          "type": "string"
        },
        "outcome": {
          "$ref": "#/$defs/CheckOutcome"
        }
      },
      "required": [
        "explanation",
        "outcome"
      ],
      "title": "QualityCheckModel",
      "type": "object"
    }
  },
  "properties": {
    "summary": {
      "title": "Summary",
      "type": "string"
    },
    "checks": {
      "$ref": "#/$defs/AnalyzeResultChecks"
    }
  },
  "required": [
